import{_ as a,o as e,c as l,a5 as i}from"./chunks/framework.a5no_H3L.js";const m=JSON.parse('{"title":"消息队列选型","description":"选消息队列不是选「最好的」，而是选「最适合的」。本章从技术维度和业务维度对比主流消息队列，给出选型决策树。","frontmatter":{},"headers":[],"relativePath":"kafka/01-intro/chapter-03-mq-comparison.md","filePath":"kafka/01-intro/chapter-03-mq-comparison.md"}'),s={name:"kafka/01-intro/chapter-03-mq-comparison.md"};function r(n,t,d,c,o,f){return e(),l("div",null,[...t[0]||(t[0]=[i(`<h1 id="消息队列选型" tabindex="-1" data-src-line="1" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">消息队列选型 <a class="header-anchor" href="#消息队列选型" aria-label="Permalink to &quot;消息队列选型&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><p data-src-line="3" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">选消息队列不是选「最好的」，而是选「最适合的」。本章从技术维度和业务维度对比主流消息队列，给出选型决策树。</p></blockquote><h2 id="_1-主流消息队列" tabindex="-1" data-src-line="5" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">1. 主流消息队列 <a class="header-anchor" href="#_1-主流消息队列" aria-label="Permalink to &quot;1. 主流消息队列&quot;">​</a></h2><table tabindex="0"><thead data-src-line="7" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><tr data-src-line="7" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><th style="text-align:left;">特性</th><th style="text-align:left;">Kafka</th><th style="text-align:left;">RabbitMQ</th><th style="text-align:left;">RocketMQ</th><th style="text-align:left;">Pulsar</th></tr></thead><tbody data-src-line="9" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><tr data-src-line="9" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">开发语言</td><td style="text-align:left;">Java/Scala</td><td style="text-align:left;">Erlang</td><td style="text-align:left;">Java</td><td style="text-align:left;">Java</td></tr><tr data-src-line="10" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">吞吐量</td><td style="text-align:left;">百万级</td><td style="text-align:left;">万级</td><td style="text-align:left;">十万级</td><td style="text-align:left;">百万级</td></tr><tr data-src-line="11" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">延迟</td><td style="text-align:left;">毫秒</td><td style="text-align:left;">微秒</td><td style="text-align:left;">毫秒</td><td style="text-align:left;">毫秒</td></tr><tr data-src-line="12" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">消息模型</td><td style="text-align:left;">发布订阅</td><td style="text-align:left;">队列/发布订阅</td><td style="text-align:left;">队列/发布订阅</td><td style="text-align:left;">发布订阅</td></tr><tr data-src-line="13" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">消息回溯</td><td style="text-align:left;">✅</td><td style="text-align:left;">❌</td><td style="text-align:left;">✅</td><td style="text-align:left;">✅</td></tr><tr data-src-line="14" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">事务消息</td><td style="text-align:left;">✅</td><td style="text-align:left;">❌</td><td style="text-align:left;">✅</td><td style="text-align:left;">✅</td></tr><tr data-src-line="15" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">流处理</td><td style="text-align:left;">✅ Streams</td><td style="text-align:left;">❌</td><td style="text-align:left;">❌</td><td style="text-align:left;">✅</td></tr><tr data-src-line="16" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">社区活跃</td><td style="text-align:left;">极高</td><td style="text-align:left;">高</td><td style="text-align:left;">高</td><td style="text-align:left;">高</td></tr></tbody></table><blockquote data-src-line="18" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><p data-src-line="18" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">吞吐量与延迟是量级经验参考，不是产品的固有能力，实际数值取决于消息大小、持久化、副本因子、确认策略和硬件。延迟测量口径（Broker 到消费者还是端到端）不同，结果差异很大。「事务消息」指生产者事务或事务消息机制，RabbitMQ 提供的是 AMQP 事务（txSelect/txCommit），语义不同且性能开销大，此处标 ❌ 只针对「事务消息」这一列，不代表 RabbitMQ 完全没有事务能力。「消息回溯」指 Kafka 任意 offset 重放能力，RabbitMQ 经典与仲裁队列不支持任意回放，RabbitMQ Streams 支持重复读取，属特殊队列类型。</p></blockquote><h2 id="_2-核心差异分析" tabindex="-1" data-src-line="20" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">2. 核心差异分析 <a class="header-anchor" href="#_2-核心差异分析" aria-label="Permalink to &quot;2. 核心差异分析&quot;">​</a></h2><h3 id="_2-1-吞吐量差异的根因" tabindex="-1" data-src-line="22" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">2.1 吞吐量差异的根因 <a class="header-anchor" href="#_2-1-吞吐量差异的根因" aria-label="Permalink to &quot;2.1 吞吐量差异的根因&quot;">​</a></h3><table tabindex="0"><thead data-src-line="24" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><tr data-src-line="24" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><th style="text-align:left;">因素</th><th style="text-align:left;">Kafka</th><th style="text-align:left;">RabbitMQ</th></tr></thead><tbody data-src-line="26" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><tr data-src-line="26" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">存储方式</td><td style="text-align:left;">分区追加日志，顺序写入</td><td style="text-align:left;">按队列类型区分，经典队列基于索引持久化，仲裁队列基于 Raft 日志</td></tr><tr data-src-line="27" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">零拷贝</td><td style="text-align:left;">消费路径 sendfile() 跳过用户态拷贝</td><td style="text-align:left;">消息经交换机路由和队列进程，需多次内存拷贝</td></tr><tr data-src-line="28" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">批量发送</td><td style="text-align:left;">生产者 batch 加消费者 Fetch 批量拉取</td><td style="text-align:left;">支持消费者 prefetch 和批量确认，投递粒度更细</td></tr><tr data-src-line="29" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">消息堆积</td><td style="text-align:left;">顺序读磁盘，堆积不显著影响吞吐</td><td style="text-align:left;">堆积增加磁盘和内存压力，长队列需关注</td></tr></tbody></table><p data-src-line="31" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">Kafka 高吞吐的完整机制见 <a href="./../04-performance/chapter-01-why-kafka-is-fast.html">为什么 Kafka 这么快</a>。</p><h3 id="_2-2-消费模型差异" tabindex="-1" data-src-line="33" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">2.2 消费模型差异 <a class="header-anchor" href="#_2-2-消费模型差异" aria-label="Permalink to &quot;2.2 消费模型差异&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Kafka（Pull）：</span></span>
<span class="line"><span>  Consumer → Broker：给我 Partition 0 从 offset 100 开始的消息</span></span>
<span class="line"><span>  消费者控制速率，不会因推送风暴而不可用</span></span>
<span class="line"><span></span></span>
<span class="line"><span>RabbitMQ（Push）：</span></span>
<span class="line"><span>  Broker → Consumer：这是新消息，你处理吧</span></span>
<span class="line"><span>  Broker 推送速率可能超过消费者处理能力</span></span></code></pre></div><p data-src-line="45" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">Pull 模型的优势：消费者控制消费速率、支持批量拉取、消费者宕机不影响 Broker。</p><p data-src-line="47" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">Push 模型的优势：实时性更好（消息到达即推送）、消费者实现更简单。</p><h3 id="_2-3-消息可靠性" tabindex="-1" data-src-line="49" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">2.3 消息可靠性 <a class="header-anchor" href="#_2-3-消息可靠性" aria-label="Permalink to &quot;2.3 消息可靠性&quot;">​</a></h3><table tabindex="0"><thead data-src-line="51" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><tr data-src-line="51" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><th style="text-align:left;">维度</th><th style="text-align:left;">Kafka</th><th style="text-align:left;">RabbitMQ</th><th style="text-align:left;">RocketMQ</th></tr></thead><tbody data-src-line="53" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><tr data-src-line="53" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">消息持久化</td><td style="text-align:left;">磁盘（可配置保留时间）</td><td style="text-align:left;">磁盘（消息与队列可持久化）</td><td style="text-align:left;">磁盘</td></tr><tr data-src-line="54" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">副本机制</td><td style="text-align:left;">ISR，可配置副本因子</td><td style="text-align:left;">经典队列（镜像功能 4.0 已移除，仲裁队列为可选替代）</td><td style="text-align:left;">同步双写</td></tr><tr data-src-line="55" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">事务</td><td style="text-align:left;">0.11+ 生产者事务</td><td style="text-align:left;">AMQP 事务（非事务消息语义）</td><td style="text-align:left;">事务消息（半消息）</td></tr><tr data-src-line="56" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">消息丢失窗口</td><td style="text-align:left;">acks=all 且 min.insync.replicas 满足时最小</td><td style="text-align:left;">消费者确认前消息可重新入队，非直接丢失</td><td style="text-align:left;">同步刷盘加同步复制时最小</td></tr></tbody></table><p data-src-line="58" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">可靠性保障要分生产端、Broker 端、消费端三个阶段看，任何单一配置都不能保证端到端不丢消息：</p><ul data-src-line="60" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><li data-src-line="60" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">生产端：Kafka 靠 <code>acks=all</code> 与 <code>min.insync.replicas</code> 确认副本写入；RabbitMQ 靠发布确认（publisher confirm）。</li><li data-src-line="61" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">Broker 端：Kafka 靠副本与 ISR；RabbitMQ 靠队列持久化与副本（仲裁队列）。</li><li data-src-line="62" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">消费端：Kafka 靠手动提交 Offset；RabbitMQ 靠消费者 ACK。</li></ul><p data-src-line="64" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">RabbitMQ 的「消费者确认前可能丢」说法不准确：消费者在 ACK 前异常断开，未确认消息会重新入队等待再次投递，除非消息被 reject 且未设置 requeue 才被丢弃。Kafka 的 <code>acks=all</code> 只等待当前 ISR 中的副本确认，还需配合 <code>min.insync.replicas</code> 并禁用非干净 Leader 选举才能最大程度避免丢失，消费端 Offset 提交属于另一阶段的保障。</p><p data-src-line="66" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">更完整的可靠性分析见 <a href="./../03-reliability/chapter-01-message-loss.html">消息丢失</a> 与 <a href="./../02-core/chapter-04-replication-and-isr.html">副本与 ISR</a>；RabbitMQ 的副本与高可用见 <a href="./../../rabbitmq/03-queue/chapter-03-quorum-queue.html">仲裁队列</a>。</p><h2 id="_3-选型决策树" tabindex="-1" data-src-line="68" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">3. 选型决策树 <a class="header-anchor" href="#_3-选型决策树" aria-label="Permalink to &quot;3. 选型决策树&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>需要消息队列</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ 高吞吐（量级参考 &gt;10万/s）+ 大数据生态 → Kafka</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ 业务消息 + 复杂路由 + 低延迟 → RabbitMQ</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ 金融级事务 + 延迟消息 → RocketMQ</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  └─ 多租户 + 存储分离 → Pulsar</span></span></code></pre></div><p data-src-line="82" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">阈值只是初筛参考，不是排除某种产品的充分条件。最终选型还要结合消息保留、路由复杂度、消费模型、延迟目标、故障语义和运维成本综合判断。</p><h2 id="_4-场景选型" tabindex="-1" data-src-line="84" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">4. 场景选型 <a class="header-anchor" href="#_4-场景选型" aria-label="Permalink to &quot;4. 场景选型&quot;">​</a></h2><table tabindex="0"><thead data-src-line="86" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><tr data-src-line="86" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><th style="text-align:left;">场景</th><th style="text-align:left;">推荐</th><th style="text-align:left;">理由</th></tr></thead><tbody data-src-line="88" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><tr data-src-line="88" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">日志收集</td><td style="text-align:left;">Kafka</td><td style="text-align:left;">高吞吐、消息回溯、ELK 生态</td></tr><tr data-src-line="89" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">事件驱动</td><td style="text-align:left;">Kafka</td><td style="text-align:left;">高吞吐、持久化、消费者组</td></tr><tr data-src-line="90" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">数据管道（CDC）</td><td style="text-align:left;">Kafka</td><td style="text-align:left;">Kafka Connect、Debezium 生态</td></tr><tr data-src-line="91" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">流式处理</td><td style="text-align:left;">Kafka</td><td style="text-align:left;">Kafka Streams / Flink 集成</td></tr><tr data-src-line="92" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">业务消息（订单/支付）</td><td style="text-align:left;">RabbitMQ 或 RocketMQ</td><td style="text-align:left;">低延迟、复杂路由、事务支持</td></tr><tr data-src-line="93" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">即时通讯</td><td style="text-align:left;">RabbitMQ</td><td style="text-align:left;">低延迟、灵活路由</td></tr><tr data-src-line="94" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">金融交易</td><td style="text-align:left;">RocketMQ</td><td style="text-align:left;">事务消息、定时消息、高可靠</td></tr></tbody></table><h2 id="_5-何时不选-kafka" tabindex="-1" data-src-line="96" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">5. 何时不选 Kafka <a class="header-anchor" href="#_5-何时不选-kafka" aria-label="Permalink to &quot;5. 何时不选 Kafka&quot;">​</a></h2><table tabindex="0"><thead data-src-line="98" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><tr data-src-line="98" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><th style="text-align:left;">场景</th><th style="text-align:left;">原因</th><th style="text-align:left;">替代方案</th></tr></thead><tbody data-src-line="100" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><tr data-src-line="100" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">消息量 &lt; 1万/s</td><td style="text-align:left;">Kafka 运维成本高，杀鸡用牛刀</td><td style="text-align:left;">RabbitMQ</td></tr><tr data-src-line="101" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">延迟要求 &lt; 1ms</td><td style="text-align:left;">Kafka 毫秒级，RabbitMQ 延迟通常更低（量级参考）</td><td style="text-align:left;">RabbitMQ</td></tr><tr data-src-line="102" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">复杂路由规则</td><td style="text-align:left;">Kafka 路由模型简单，Topic 加分区键分配</td><td style="text-align:left;">RabbitMQ（Exchange/Binding）</td></tr><tr data-src-line="103" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><td style="text-align:left;">小团队无 Java 技术栈</td><td style="text-align:left;">Kafka 运维需要 JVM 经验</td><td style="text-align:left;">RabbitMQ 或云服务</td></tr></tbody></table><blockquote data-src-line="105" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><p data-src-line="105" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">表中阈值（&lt; 1万/s、&lt; 1ms）同为经验参考，需结合具体工作负载判断。低吞吐但要求复杂路由的业务更适合 RabbitMQ，吞吐不高但需要长期保留和重复读取的事件流仍可能适合 Kafka。RabbitMQ 的复杂路由能力见 <a href="./../../rabbitmq/02-exchange/chapter-01-exchange-basics.html">Exchange 基础</a>。</p></blockquote><h2 id="_6-混合使用" tabindex="-1" data-src-line="107" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">6. 混合使用 <a class="header-anchor" href="#_6-混合使用" aria-label="Permalink to &quot;6. 混合使用&quot;">​</a></h2><p data-src-line="109" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">大型系统中可以同时使用多种消息队列：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>业务消息（订单/支付）→ RabbitMQ（低延迟、复杂路由）</span></span>
<span class="line"><span>日志/事件           → Kafka（高吞吐、持久化）</span></span>
<span class="line"><span>数据管道            → Kafka Connect（CDC 生态）</span></span></code></pre></div><blockquote data-src-line="117" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md"><p data-src-line="117" data-src-file="kafka/01-intro/chapter-03-mq-comparison.md">不要为了「统一技术栈」而强行用一个消息队列解决所有问题。Kafka 擅长大数据量、高吞吐；RabbitMQ 擅长业务消息、灵活路由。各取所长。</p></blockquote>`,31)])])}const k=a(s,[["render",r]]);export{m as __pageData,k as default};
